// coding-misk · Example 2 · Bass and chords
// song composed with sections and tracks: each track plays its clips, switched on by the section lane (1 plays, 0 is silent, values in between fade)
// each .analyze("…") lights up its instrument in the Stage visual
setcpm(110/4)

const SECTIONS = [['Crescendo', 6], ['Crescendo 2', 26], ['Verse', 8], ['Chorus', 8]]
const TEMPO = {'Crescendo': 110, 'Crescendo 2': 110, 'Verse': 110, 'Chorus': 110}

// section lanes: 1 plays, 0 is silent, values in between fade
const section1 = "<1!6 0!42>"  // Crescendo · 6 bars · 110 BPM · E · Em
const section2 = "<0!6 1!26 0!16>"  // Crescendo 2 · 26 bars · 110 BPM · E · Em C G D
const section3 = "<0!32 1!8 0!8>"  // Verse · 8 bars · 110 BPM · E · Em Bm C D
const section4 = "<0!40 1!8>"  // Chorus · 8 bars · 110 BPM · E · Em C G D

// ========== drums ==========
// Crescendo · bars 1-6 · pattern chorus~3
// Drums · RolandTR808
$: s("[bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~]").bank("RolandTR808").gain(0.9).mask(section1).velocity(section1).orbit(1).analyze("kick")
$: s("~ [cp ~ ~ ~] ~ [cp ~ ~ ~]").bank("RolandTR808").gain(0.72).mask(section1).velocity(section1).orbit(1).analyze("snare")
$: s("[hh ~ ~ ~] ~ ~ ~").bank("RolandTR808").gain(0.45).mask(section1).velocity(section1).orbit(1).analyze("hats")
// Crescendo 2 · bars 7-32 · pattern chorus~3
$: s("[bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~] [bd ~ ~ ~]").bank("RolandTR808").gain(0.9).mask(section2).velocity(section2).orbit(1).analyze("kick")
$: s("~ [cp ~ ~ ~] ~ [cp ~ ~ ~]").bank("RolandTR808").gain(0.72).mask(section2).velocity(section2).orbit(1).analyze("snare")
$: s("[hh ~ ~ ~] ~ ~ ~").bank("RolandTR808").gain(0.45).mask(section2).velocity(section2).orbit(1).analyze("hats")
